mapper.select:
select count(1) from b_marketing_sync_${apiCode}
where
applet_date = #{uploadDate,jdbcType=VARCHAR} and
(user_type = #{userType,jdbcType=VARCHAR} or group_type = #{userType,jdbcType=VARCHAR})

  and status = #{status,jdbcType=INTEGER}
  and is_repeat in(1,2)

select applet_date
from b_marketing_sync_${apiCode}
where user_type = #{userType}
and   create_time >= #{startDate} and create_time < #{endDate} and applet_date >= #{appletDateStart}
group by applet_date order by applet_date asc

mapper.update:
update b_marketing_sync_report
set normal_num = #{normalNum,jdbcType=INTEGER},
  duplicate_removal_num = #{duplicateRemovalNum,jdbcType=INTEGER},
  applet_end_time = #{appletEndTime,jdbcType=TIMESTAMP},
  reserve_field1_key =#{reserveField1Key,jdbcType=VARCHAR}
where id = #{id,jdbcType=BIGINT}

mapper.select:
select id, cid , api_code , short_name as shortName , applet_date as appletDate , user_type as userType , normal_num as normalNum , duplicate_removal_num as duplicateRemovalNum , DATE_FORMAT(bmsr.applet_begin_time,'%Y-%m-%d %H:%i:%s') as appletBeginTime , DATE_FORMAT(bmsr.applet_end_time,'%Y-%m-%d %H:%i:%s') as appletEndTime , remark , DATE_FORMAT(bmsr.create_time,'%Y-%m-%d %H:%i:%s') as createTime , DATE_FORMAT(bmsr.update_time,'%Y-%m-%d %H:%i:%s') as updateTime , label_message as labelMessage from b_marketing_sync_report bmsr
and bmsr.applet_date >=#{appletTimeStart}
and bmsr.applet_date <#{appletTimeEnd}
and bmsr.api_code in
#{item}
and bmsr.user_type in
#{item}
and (bmsr.cid like concat("%", #{cidOrName},"%") or bmsr.short_name like concat("%", #{cidOrName},"%"))
order by bmsr.applet_date desc,bmsr.create_time desc,bmsr.id desc

select bmsr.id , bmsr.cid , bmsr.api_code , bmsr.short_name as shortName , bmsr.applet_date as appletDate , bmsr.user_type as userType , bmsr.normal_num as normalNum , bmsr.duplicate_removal_num as duplicateRemovalNum , DATE_FORMAT(bmsr.applet_begin_time,'%Y-%m-%d %H:%i:%s') as appletBeginTime , DATE_FORMAT(bmsr.applet_end_time,'%Y-%m-%d %H:%i:%s') as appletEndTime , bmsr.remark , DATE_FORMAT(bmsr.create_time,'%Y-%m-%d %H:%i:%s') as createTime , DATE_FORMAT(bmsr.update_time,'%Y-%m-%d %H:%i:%s') as updateTime , bmsr.label_message as labelMessage , COALESCE(bmvd.valid_start_date, '') as validStartDate , COALESCE(bmvd.valid_end_date, '') as validEndDate from b_marketing_sync_report bmsr LEFT JOIN b_marketing_data_valid_config bmvd ON bmsr.api_code = bmvd.api_code AND bmsr.user_type = bmvd.user_type AND bmsr.applet_date = bmvd.applet_date
and bmsr.applet_date >=#{appletTimeStart}
and bmsr.applet_date <#{appletTimeEnd}
and bmsr.api_code in
#{item}
and bmsr.user_type in
#{item}
and (bmsr.cid like concat("%", #{cidOrName},"%") or bmsr.short_name like concat("%", #{cidOrName},"%"))
order by bmsr.applet_date desc,bmsr.create_time desc,bmsr.id desc

select SUM(normal_num) as normalNumTotal,SUM(duplicate_removal_num) as duplicateRemovalNumTotal,
       api_code
from b_marketing_sync_report bmsr


      and bmsr.applet_date >=#{appletTimeStart} 


      and bmsr.applet_date <#{appletTimeEnd} 


    and bmsr.api_code in

      #{item}



    and bmsr.user_type in

      #{item}



    and (bmsr.cid like concat("%", #{cidOrName},"%")
    or bmsr.short_name like concat("%", #{cidOrName},"%"))


group by api_code

select *
from b_marketing_sync_report
where id = #{id}

select *
from b_marketing_data_valid_config
where api_code = #{apiCode}
and user_type = #{userType}
and applet_date =#{appletDate}

select distinct(json_keys(reserve_field1))
from b_marketing_sync_${apiCode}
where user_type = #{userType}
  and applet_date = #{appletDate}

select id,api_code,reserve_field1 from b_marketing_sync_${apiCode}


    user_type = #{userType}


    and ${extend}



      and applet_date = #{list[0]}


      and applet_date in

        #{item}



  and status =1 and is_repeat in (1, 2)

    and id > #{indexId}

  order by id asc limit #{pageSize};

select count(1) as num,${field} as field
from b_marketing_sync_${apiCode}



      (applet_date = #{item.appletDate} and user_type = #{item.userType})


  and json_valid(reserve_field1)=1 and status =1 and is_repeat in (1, 2)

    and ${extendField} is not null

  group by ${field};

select id,api_code,reserve_field1 from b_marketing_sync_${apiCode}



      (applet_date = #{item.appletDate} and user_type = #{item.userType})



    and ${extend}

  and status =1 and is_repeat in (1, 2)

    and id > #{indexId}

  order by id asc limit #{pageSize};

select max(id)as maxId,min(id) as minId from (
select id from b_marketing_sync_${apiCode}

    ${sqlCondition}

    and id > #{indexId}

  order by id asc limit #{groupNum} ) a

select operate_type, applet_date, user_type from b_marketing_sync_${apiCode}


    and (applet_date, user_type) in

      (#{item.appletDate}, #{item.userType})


  group by operate_type,applet_date,user_type
  ORDER BY operate_type, applet_date;
